l\\":\\"field_63ec96e3878e0\\",\\"ws_trip_information_list_2_ws_itinerary_food\\":\\"Breakfast, Lunch \\\\u0026 Dinner\\",\\"_ws_trip_information_list_2_ws_itinerary_food\\":\\"field_63ec96f1878e1\\",\\"ws_trip_information_list_2_ws_itinerary_description\\":\\"After breakfast drive back to Kathmandu via Bhaktapur. Drive or Fly to Chitwan. Lunch upon arrival then Village Tour and Sunset view from beach of Rapti river.\\",\\"_ws_trip_information_list_2_ws_itinerary_description\\":\\"field_63ec9456679f6\\",\\"ws_trip_information_list_3_di_days\\":\\"04\\",\\"_ws_trip_information_list_3_di_days\\":\\"field_63ec958b8c799\\",\\"ws_trip_information_list_3_ws_itinerary_title\\":\\"​Chitwan Tour\\",\\"_ws_trip_information_list_3_ws_itinerary_title\\":\\"field_63ec945663e31\\",\\"ws_trip_information_list_3_ws_itinerary_Elevation\\":\\"815m\\",\\"_ws_trip_information_list_3_ws_itinerary_Elevation\\":\\"field_63ec967a59e99\\",\\"ws_trip_information_list_3_ws_itinerary_duration\\":\\"\\",\\"_ws_trip_information_list_3_ws_itinerary_duration\\":\\"field_63ec96a0878df\\",\\"ws_trip_information_list_3_ws_itinerary_hotel\\":\\"3star to Luxury hotels\\",\\"_ws_trip_information_list_3_ws_itinerary_hotel\\":\\"field_63ec96e3878e0\\",\\"ws_trip_information_list_3_ws_itinerary_food\\":\\"Breakfast, Lunch \\\\u0026 Dinner\\",\\"_ws_trip_information_list_3_ws_itinerary_food\\":\\"field_63ec96f1878e1\\",\\"ws_trip_information_list_3_ws_itinerary_description\\":\\"Jungle walk after early morning Tea or Coffee. After breakfast we do Canoeing and Elephant breeding center. After Lunch for Elephant ride, in the Evening we do Cultural program and Dinner.\\",\\"_ws_trip_information_list_3_ws_itinerary_description\\":\\"field_63ec9456679f6\\",\\"ws_trip_information_list_4_di_days\\":\\"05\\",\\"_ws_trip_information_list_4_di_days\\":\\"field_63ec958b8c799\\",\\"ws_trip_information_list_4_ws_itinerary_title\\":\\"​Chitwan to Pokhara Drive\\",\\"_ws_trip_information_list_4_ws_itinerary_title\\":\\"fie