": "", "ws_trip_information_list_3_ws_itinerary_duration": "", "ws_trip_information_list_4_ws_itinerary_duration": "", "ws_trip_information_list_5_ws_itinerary_duration": "", "ws_trip_information_list_6_ws_itinerary_duration": "", "ws_trip_information_list_7_ws_itinerary_duration": "", "ws_trip_information_list_8_ws_itinerary_duration": "", "ws_trip_information_list_9_ws_itinerary_duration": "", "_ws_trip_information_list_0_ws_itinerary_duration": "field_63ec96a0878df", "_ws_trip_information_list_1_ws_itinerary_duration": "field_63ec96a0878df", "_ws_trip_information_list_2_ws_itinerary_duration": "field_63ec96a0878df", "_ws_trip_information_list_3_ws_itinerary_duration": "field_63ec96a0878df", "_ws_trip_information_list_4_ws_itinerary_duration": "field_63ec96a0878df", "_ws_trip_information_list_5_ws_itinerary_duration": "field_63ec96a0878df", "_ws_trip_information_list_6_ws_itinerary_duration": "field_63ec96a0878df", "_ws_trip_information_list_7_ws_itinerary_duration": "field_63ec96a0878df", "_ws_trip_information_list_8_ws_itinerary_duration": "field_63ec96a0878df", "_ws_trip_information_list_9_ws_itinerary_duration": "field_63ec96a0878df", "ws_trip_information_list_0_ws_itinerary_Elevation": "1400m", "ws_trip_information_list_10_ws_itinerary_duration": "", "ws_trip_information_list_1_ws_itinerary_Elevation": "1400m", "ws_trip_information_list_2_ws_itinerary_Elevation": "2175m", "ws_trip_information_list_3_ws_itinerary_Elevation": "1400m", "ws_trip_information_list_4_ws_itinerary_Elevation": "2774m", "ws_trip_information_list_5_ws_itinerary_Elevation": "5200m", "ws_trip_information_list_6_ws_itinerary_Elevation": "4348m", "ws_trip_information_list_7_ws_itinerary_Elevation": "5039m", "ws_trip_information_list_8_ws_itinerary_Elevation": "3656m", "ws_trip_information_list_9_ws_itinerary_Elevation": "3656m", "_ws_trip_information_list_0_ws_itinerary_Elevation": "field_63ec967a59e99", "_ws_trip_information_list_10_ws_itinerary_duration": "field_63ec96a0878df", "_ws_trip_information_list_1_ws_itinerary_Elevation": "field_63ec967a59e99", "_ws_trip_information_list_2_ws_itinerary_Elevation": "field_63ec967a59e99", "_ws_trip_information_list_3_ws_itinerary_Elevation": "field_63ec967a59e99", "_ws_trip_information_list_4_ws_itinerary_Elevation": "field_63ec967a59e99", "_ws_trip_information_list_5_ws_itinerary_Elevation": "field_63ec967a59e99", "_ws_trip_information_list_6_ws_itinerary_Elevation": "field_63ec967a59e99", "_ws_trip_information_list_7_ws_itinerary_Elevation": "field_63ec967a59e99", "_ws_trip_information_list_8_ws_itinerary_Elevation": "field_63ec967a59e99", "_ws_trip_information_list_9_ws_itinerary_Elevation": "field_63ec967a59e99", "ws_trip_information_list_10_ws_itinerary_Elevation": "", "_ws_trip_information_list_10_ws_itinerary_Elevation": "field_63ec967a59e99", "ws_trip_information_list_0_ws_itinerary_description": "Airport transfer, collect your original passport and photographs to submit the Chinese embassy for Tibet visa.", "ws_trip_information_list_1_ws_itinerary_description": "Boudhanath Stupa, Pashupatinath Temple, Patan Durbar Square", "ws_trip_information_list_2_ws_itinerary_description": "Swoyambhunath Temple (Monkey Temple), Bhaktapur Durbar Square and Nagarkot for sunset and sunrise view.", "ws_trip_information_list_3_ws_itinerary_description": "Sunrise tour, Panauti Village tour, Namobuddha Monastery, drive to Kathmandu and collect your Tibet visa with your original passport from Chinese embassy of Kathmandu.", "ws_trip_information_list_4_ws_itinerary_description": "Drive to Gyirung (Nepal Tibet border)", "ws_trip_information_list_5_ws_itinerary_description": "Sunset of Everest Peak, Everest Base Camp, Far view of the Mt.Shishapangma, Tongla Pass Himalaya Mountain Range View.", "ws_trip_information_list_6_ws_itinerary_description": "Sunrise view of Golden Everest peak from Rongbuk and drive to Shigatse, Tashilhunpo Monastery visit.", "ws_trip_information_list_7_ws_itinerary_description": "Yamdrok Lake, Karola Glacier, Pelkor Chöde Monastery with Gyantse Kumbum.", "ws_trip_information_list_8_ws_itinerary_description": "Potala Palace, Jokhang Temple, Barkhor Street", "ws_trip_information_list_9_ws_itinerary_description": "Drepung Monastery and Sera Monastery", "_ws_trip_information_list_0_ws_itinerary_description": "field_63ec9456679f6", "_ws_trip_information_list_1_ws_itinerary_description": "field_63ec9456679f6", "_ws_trip_information_list_2_ws_itinerary_description": "field_63ec9456679f6", "_ws_trip_information_list_3_ws_itinerary_description": "field_63ec9456679f6", "_ws_trip_information_list_4_ws_itinerary_description": "field_63ec9456679f6", "_ws_trip_information_list_5_ws_itinerary_description": "field_63ec9456679f6", "_ws_trip_information_list_6_ws_itinerary_description": "field_63ec9456679f6", "_ws_trip_information_list_7_ws_itinerary_description": "field_63ec9456679f6", "_ws_trip_information_list_8_ws_itinerary_description": "field_63ec9456679f6", "_ws_trip_information_list_9_ws_itinerary_description": "field_63ec9456679f6", "ws_trip_information_list_10_ws_itinerary_description": "Airport transfer, Flight to next destination or your home from Lhasa Gonggar airport via Chengdu/Beijing/Kunming etc.", "_ws_trip_information_list_10_ws_itinerary_description": "field_63ec9456679f6"}, "categoryId": null, "meta_title": "Nepal Tibet Overland Tour with Everest Base Camp | Everest Vacation", "blogContent": "<!-- wp:acf/starter-kit-trip-fact {\\"name\\":\\"acf/starter-kit-trip-fact\\",\\"data\\":{\\"starter_kit_section_padding\\":\\"\\",\\"_starter_kit_section_padding\\":\\"field_5f3e0f86a2634\\",\\"starter_kit_padding_type\\":\\"p-medium\\",\\"_starter_kit_padding_type\\":\\"field_5f8584c998bc2\\",\\"starter_kit_enable_section\\":\\"1\\",\\"_starter_kit_enable_section\\":\\"field_63ec73a6998bb\\",\\"ws_trip_fact_short_description\\":\\"\\",\\"_ws_trip_fact_short_description\\":\\"field_63ec73a69d305\\",\\"ws_trip_block_highlights\\":\\"\\\\u003ch3\\\\u003eOverland tour with EBC/Rongbuk monastery (4 nights Kathmandu and 6 nights Tibet)\\\\u003c/h3\\\\u003e\\\\r\\\\n\\\\u003cul\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003e\\\\u003cstrong\\\\u003eProcess/Route: \\\\u003c/strong\\\\u003eArrival in Kathmandu, visa processing, Nagarkot, drive to Gyirung (Nepal Tibet border), Rongbuk Monastery (EBC viewpoint), Shigatse, Yamdrok Lake, Lhasa city tour and flight from Lhasa to next destination via China mainland; eg: Chengdu/Beijing/Kunming, etc.\\\\u003c/li\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003e\\\\u003cstrong\\\\u003eAlternate Process/Route: \\\\u003c/strong\\\\u003eArrival in Lhasa from your country via mainland China; eg: Chengdu/Beijing/Kunming etc. (\\\\u003cem\\\\u003e1 night overnight stay at China city to collect a Tibet travel permit, which we will send you before you arrive in a hotel or, if there is enough time to fly to Lhasa in same day, we can handover at the airport.\\\\u003c/em\\\\u003e), Lhasa city tour, Yamdrok lake, Shigatse, Rongbuk monastery (EBC), Gyirung and drive to Kathmandu, Kathmandu Tour, flight out from Kathmandu to home or next destination.\\\\u003c/li\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003e\\\\u003cstrong\\\\u003eAccommodation Limit: \\\\u003c/strong\\\\u003eNo luxury/5 star/4 star hotels in Rongbuk monastery (monastery/guesthouse/tent available) and Gyirung (locally 3 star hotel available).\\\\u003c/li\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003e\\\\u003cstrong\\\\u003eAbout Road: \\\\u003c/strong\\\\u003eKathmandu to Rasuwa Gadhi takes around 6-7 hours, and travels over some gravel and dirt roads that are only single lane, often causing traffic issues.\\\\u003c/li\\\\u003e\\\\r\\\\n\\\\u003c/ul\\\\u003e\\\\r\\\\nAn \\\\u003cstrong\\\\u003eOverland Nepal Tibet Tour with EBC\\\\u003c/strong\\\\u003e is an exciting package designed by Everest Vacation to cater to a unique experience for travelers. The highlight of this overland tour between Nepal and Tibet is the flexibility to start either from Nepal or Tibet.\\\\r\\\\n\\\\r\\\\nThe overland tour to Tibet allows visitors to witness scenic snow-covered Himalayas and beautiful surroundings. It takes you up close to the iconic Northern Everest Base Camp and admired highest-elevated Rongbuk Monastery. The holy sites in Shigatse, UNESCO Heritage sites in Lhasa (Potala Palace, Jokhang Temple, etc.), holy monasteries, distinct Tibetan culture, and serene lakes mesmerize everyone.\\\\r\\\\n\\\\r\\\\nLikewise, in Kathmandu, the ancient Durbar Squares (UNESCO Heritage sites), old traditional villages (Panauti, Namo Buddha), and scenic sunrise over the majestic Himalayas in Nagarkot experiencing is surreal. The tour is a perfect combo of nature and culture replicating the significance of these majestic places.\\",\\"_ws_trip_block_highlights\\":\\"field_63ec73a6a0d8f\\",\\"ws_block_trip_grading\\":\\"\\",\\"_ws_block_trip_grading\\":\\"field_63ec73a6a4716\\",\\"ws_block_max_elevation\\":\\"\\",\\"_ws_block_max_elevation\\":\\"field_63eeee07072d9\\",\\"ws_block_attractions\\":\\"\\",\\"_ws_block_attractions\\":\\"field_63eeee1f072da\\",\\"ws_block_best_season\\":\\"\\",\\"_ws_block_best_season\\":\\"field_63eeee37072db\\",\\"ws_block_meals\\":\\"\\",\\"_ws_block_meals\\":\\"field_63eeee4e072dc\\",\\"ws_block_accommodation\\":\\"\\",\\"_ws_block_accommodation\\":\\"field_63eeee62072dd\\",\\"ws_block_transportation\\":\\"\\",\\"_ws_block_transportation\\":\\"field_63eeee74072de\\",\\"ws_block_start_end\\":\\"\\",\\"_ws_block_start_end\\":\\"field_63eeee8b072df\\"},\\"mode\\":\\"edit\\"} /-->\\n\\n<!-- wp:acf/starter-kit-trip-fact {\\"name\\":\\"acf/starter-kit-trip-fact\\",\\"data\\":{\\"starter_kit_section_padding\\":\\"\\",\\"_starter_kit_section_padding\\":\\"field_5f3e0f86a2634\\",\\"starter_kit_padding_type\\":\\"p-medium\\",\\"_starter_kit_padding_type\\":\\"field_5f8584c998bc2\\",\\"starter_kit_enable_section\\":\\"1\\",\\"_starter_kit_enable_section\\":\\"field_63ec73a6998bb\\",\\"ws_trip_fact_short_description\\":\\"Tour Highlights\\",\\"_ws_trip_fact_short_description\\":\\"field_63ec73a69d305\\",\\"ws_trip_block_highlights\\":\\"\\\\u003cul\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003eKathmandu sightseeing including UNESCO World Heritage Sites (Durbar Squares, Boudhanath,  Pashupatinath)\\\\u003c/li\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003eDrive to Nagarkot for a panoramic view of the Himalayas and Kathmandu valley (Sunset / Sunrise also popular)\\\\u003c/li\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003eAuthentic Village Tours (Panauti and Namo Buddha)\\\\u003c/li\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003eUNESCO-listed royal museum Potala Palace includes 1,000 rooms, 10,000 shrines, and approx. 200,000 statues\\\\u003c/li\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003eHoly Barkhor Street popular for the Kora ritual and for buying Tibetan original goods\\\\u003c/li\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003eSpiritual Buddhist Sacred Jokhang Temple\\\\u003c/li\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003eVisit the holy Sera Monastery famous for debate sessions (between 3-5 pm)\\\\u003c/li\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003eNorbulingka Palace with its unique Tibetan architecture popular for the Yogurt festival (Sho Dun)\\\\u003c/li\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003eVisit the freshwater sacred Yamdrok Lake\\\\u003c/li\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003eShigatse Sightseeing (Tashilhunpo Monastery, Shigatse Dzong, Sakya Monastery, etc.)\\\\u003c/li\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003eOne of the highest-elevated Monastery in the world-Rongbuk Monastery\\\\u003c/li\\\\u003e\\\\r\\\\n \\\\t\\\\u003cli\\\\u003eIconic Northern Everest Base Camp Trek\\\\u003c/li\\\\u003e\\\\r\\\\n\\\\u003c/ul\\\\u003e\\",\\"_ws_trip_block_highlights\\":\\"field_63ec73a6a0d8f\\",\\"ws_block_trip_grading\\":\\"\\",\\"_ws_block_trip_grading\\":\\"field_63ec73a6a4716\\",\\"ws_block_max_elevation\\":\\"\\",\\"_ws_block_max_elevation\\":\\"field_63eeee07072d9\\",\\"ws_block_a