on\\":\\"\\",\\"_ws_trip_information_list_8_ws_itinerary_description\\":\\"field_63ec9456679f6\\",\\"ws_trip_information_list_9_di_days\\":\\"09\\",\\"_ws_trip_information_list_9_di_days\\":\\"field_63ec958b8c799\\",\\"ws_trip_information_list_9_ws_itinerary_title\\":\\"Fly Jomsom to Pokhara 30min and Drive to Kathmandu\\",\\"_ws_trip_information_list_9_ws_itinerary_title\\":\\"field_63ec945663e31\\",\\"ws_trip_information_list_9_ws_itinerary_Elevation\\":\\"3850m\\",\\"_ws_trip_information_list_9_ws_itinerary_Elevation\\":\\"field_63ec967a59e99\\",\\"ws_trip_information_list_9_ws_itinerary_duration\\":\\" 5-6 hrs\\",\\"_ws_trip_information_list_9_ws_itinerary_duration\\":\\"field_63ec96a0878df\\",\\"ws_trip_information_list_9_ws_itinerary_hotel\\":\\"\\",\\"_ws_trip_information_list_9_ws_itinerary_hotel\\":\\"field_63ec96e3878e0\\",\\"ws_trip_information_list_9_ws_itinerary_food\\":\\"\\",\\"_ws_trip_information_list_9_ws_itinerary_food\\":\\"field_63ec96f1878e1\\",\\"ws_trip_information_list_9_ws_itinerary_description\\":\\"\\",\\"_ws_trip_information_list_9_ws_itinerary_description\\":\\"field_63ec9456679f6\\",\\"ws_trip_information_list\\":10,\\"_ws_trip_information_list\\":\\"field_63ec94565c587\\",\\"ws_flash_message_title\\":\\"\\",\\"_ws_flash_message_title\\":\\"field_63ec94c094a17\\",\\"ws_flash_message_text\\":\\"\\",\\"_ws_flash_message_text\\":\\"field_63ec950194a18\\"},\\"mode\\":\\"edit\\"} /-->\\n\\n<!-- wp:acf/starter-kit-testimonial-lists {\\"name\\":\\"acf/starter-kit-testimonial-lists\\",\\"data\\":{\\"starter_kit_section_padding\\":\\"\\",\\"_starter_kit_section_padding\\":\\"field_5f3e0f86a2634\\",\\"starter_kit_padding_type\\":\\"p-medium\\",\\"_starter_kit_padding_type\\":\\"field_5f8584c998bc2\\",\\"starter_kit_enable_section\\":\\"1\\",\\"_starter_kit_enable_section\\":\\"field_63ba53af63ade\\",\\"starter_kit_testimonial_title\\":\\"Traveler's Reviews\\",\\"_starter_kit_testimonial_title\\":\\"field_63ba53af6b053\\",\\"review_number_of_post\\":\\"\\",\\"_review_number_of_post\\":\\"field_63ba542aa9a32\\"},\\"mode\\":\\"edit\\"} /-->\\n\\n<!-- wp:acf/starter-kit-quick-enquiry {\\"name\\":\\"acf/starter-kit-quick-enquiry\\",\\"data\\":{\\"starter_kit_enable_section\\":\\"1\\",\\"_starter_kit_enable_section\\":\\"field_63edeb1c7635c\\",\\"ws_quick_enquiry_title\\":\\"Ask to Expert about this trip\\",\\"_ws_quick_enquiry_title\\":\\"field_63edeb1c7d769\\",\\"ws_quick_enquiry_desc\\":\\"Fill the form below for your interest.\\\\r\\\\n\\",\\"_ws_quick_enquiry_desc\\":\\"field_63edeb1c811ab\\",\\"ws_gf_id\\":\\"4\\",\\"_ws_gf_id\\":\\"field_63edec7318284\\",\\"starter_kit_section_padding\\":\\"\\",\\"_starter_kit_section_padding\\":\\"field_5f3e0f86a2634\\",\\"starter_kit_padding_type\\":\\"p-medium\\",\\"_starter_kit_padding_type\\":\\"field_5f8584c998bc2\\"},\\"mode\\":\\"edit\\"} /-->", "imageGallary": ["https://everestnepaltours.com/wp-content/uploads/2023/12/bells-in-muktinath-temple.jpg"], "importSource": {"guid": "https://wildstonesolution.com/demo/ev/?post_type=trip&#038;p=3517", "system": "wordpress", "parentId": 0, "postType": "trip", "wpPostId": "3517", "wpSiteUrl": "https://everestnepaltours.com", "postStatus": "publish", "tablePrefix": "wev_", "wpContentDir": "/Users/pasangrumba/Documents/Work/JavaScript_Projects/everestnepaltours_wordpress/wp-content", "sourceTimestamps": {"post_date": "2024-01-04 06:07:43", "post_date_gmt": "2024-01-04 06:07:43", "post_modified": "2024-02-08 07:07:28", "post_modified_gmt": "2024-02-08 07:07:28"}}, "customSections": [{"id": "overview-1", "type": "paragraph", "title": "Overview", "content": ["10 days <a href=\\"https://everestnepaltours.com/jomsom-muktinath-4wd-tour/\\">Jomsom Muktinath</a> Trekking in Nepal is an amazing trek in the Annapurna region. Starting with a scenic drive from Kathmandu to Pokhara, the trek commences with a drive to Nayapul and a walk to Tikhedhunga. Traverse through beautiful settlements and experience a local lifestyle living there. <a href=\\"https://en.wikipedia.org/wiki/Marpha\\" target=\\"_blank\\" rel=\\"noopener\\">Marpha</a> is famous for apple farming and brandy. Try some or get some as a souvenir. Reach Muktinath, the holy temple at an elevation of 3,800m. Visit the temple and adore the surrounding scenic landscapes."], "description": "10 days <a href=\\"https://everestnepaltours.com/jomsom-muktinath-4wd-tour/\\">Jomsom Muktinath</a> Trekking in Nepal is an amazing trek in the Annapurna region. Starting with a scenic drive from Kathmandu to Pokhara, the trek commences with a drive to Nayapul and a walk to Tikhedhunga. Traverse through beautiful settlements and experience a local lifestyle living there. <a href=\\"https://en.wikipedia.org/wiki/Marpha\\" target=\\"_blank\\" rel=\\"noopener\\">Marpha</a> is famous for apple farming and brandy. Try some or get some as a souvenir. Reach Muktinath, the holy temple at an elevation of 3,800m. Visit the temple and adore the surrounding scenic landscapes."}], "itinerary_title": "Upper Mustang Trek", "sub_description": "Explore Jomsom Muktinath Trekking with Everest Vacation.", "trip_type_level": "Challenging", "meta_description": "Jomsom Muktinath Trekking is an exciting trip that is a great blend of culture and nature offering unique experiences to travelers.", "related_trip_facts": {"meals": "", "start_end": "", "attractions": "", "best_season": "", "accommodation": "", "max_elevation": "", "transportation": ""}}	2024-01-04 06:07:43+00	2024-02-08 07:07:28+00
229	{"acf": {"ws_sale_price": "", "ws_short_desc": "", "ws_dulux_price": "", "ws_regular_price": "", "ws_number_of_days": "11", "child_select_quick_link": "a:5:{i:0;s:8:\\"overview\\";i:1;s:7:\\"essinfo\\";i:2;s:9:\\"itinerary\\";i:3;s:7:\\"reviews\\";i:4;s:4:\\"faqs\\";}", "ws_trips_difficulty_level": "Moderate"}, "faq": [{"answer": "Located in Nepal, Base camp is located at 5300 meter, Everest is 8,848 meter from sea level.", "question": "Where is Everest Base Camp? how high is it ?"}, {"answer": "Two weeks for trekking in both ways but allow few extra days for preparations.", "question": "How long does it take to climb Mount Everest Base Camp?"}, {"answer": "Depend on hotels choices and services need. Minimum cost is USD 1000 per person", "question": "How much does it cost to trek Everest base camp ?"}, {"answer": "Be prepared for freezing zero, so bring Down Jackets and all warm clothes including sleeping bag.", "question": "Clothing for Everest base camp trekking ?"}], "meta": {"_edit_last": "5", "_edit_lock": "1707378862:5", "_dp_original": "753", "_thumbnail_id": "757", "ws_sale_price": "", "ws_short_desc": "", "_ws_sale_price": "field_63ec6cbabf59a", "_ws_short_desc": "field_64bcfed7ea657", "ws_dulux_price": "", "_ws_dulux_price": "field_64bcfed7ea657", "ws_regular_price": "", "_ws_regular_price": "field_63ec6b81bf599", "ws_number_of_days": "11", "_ws_number_of_days": "field_63ec6d011465f", "_yoast_wpseo_title": "Everest Base Camp Trekking", "_yoast_wpseo_focuskw": "Everest Base Camp Trekking", "_yoast_wpseo_linkdex": "47", "_yoast_wpseo_metadesc": "Everest Base Camp Trekking is in most traveler's bucket-list mesmerizing with scenic vistas, local lifestyle, iconic Everest Base Camp.", "child_select_quick_link": "a:5:{i:0;s:8:\\"overview\\";i:1;s:7:\\"essinfo\\";i:2;s:9:\\"itinerary\\";i:3;s:7:\\"reviews\\";i:4;s:4:\\"faqs\\";}", "_child_select_quick_link": "field_643ed174633ee", "ws_trips_difficulty_level": "Moderate", "_ws_trips_difficulty_level": "field_63ec7097385a5", "_yoast_wpseo_primary_activity": "", "_yoast_wpseo_primary_destination": "", "_yoast_wpseo_wordproof_timestamp": "", "_yoast_wpseo_estimated-reading-time-minutes": "1"}, "slug": "everest-base-camp-trekking", "tags": [], "title": "Everest Base Camp Trekking", "duration": "11 Days", "overview": {"title": "Overview", "description": "<strong>Everest base camp Trekking cost and plan in depth – reasonable budget price\\r\\n</strong>\\r\\n\\r\\nDream trip of a lifetime on land, Everest base camp trekking is the most famous trekking adventure in the world. Everest is the highest peak,  8848.86 meters (29,029 feet) but base camp is 5300 meters (17,600 feet) only.  Join our well-organized small group trekking to Everest base camp in two weeks or a private custom itinerary also available on a daily departure basis.\\r\\n\\r\\nSpend a few days in the historic cultural capital Kathmandu where Buddhist stupas, Hindu temples, and five-hundred-year-old royal palaces are making the city vibrant.  Spin the prayer wheels, and chant the mantra ‘OM MANI PADME HUM’ meaning HAIL TO THE JEWEL ON THE LOTUS.\\r\\n\\r\\nStroll around the 17th-century alleyways. Start hiking the trails with the sound of yak bells, and trekking porters’ melodious songs.  Meditate in the prayer hall while monks are praying and drink Tibetan tea with monks, chanting their mantras together. Enjoy Sherpa soup (Sherpa stew), Yak steak, Tongba (alcohol for Sherpa), Raksi (rice wine) drink Salt tea or butter tea to keep you warm during the morning. Talk to Sherpa Porter and try to carry their heavy loads. Learn to cook Dal-Bhat and taste with our trekking safe.\\r\\n\\r\\nFly to Lukla and follow the traditional trekking route but our guide organizes through visits to hidden gems and surprises every day. make photographs of sunrise and sunset views on the summit of Everest, Amadablam, and more…  enjoy the holiday. plan in advance and also for <a href=\\"https://www.nepalimmigration.gov.np/\\" target=\\"_blank\\" rel=\\"noopener\\">the visa process</a> to enter Nepal.\\r\\n<h3>Outline Itinerary</h3>\\r\\n<strong>01 Day:</strong> Early morning, Magnificent flight to Lukla then walk through forest and Sherpa settlement to Manju.\\r\\n<strong>02 Day:</strong> Walk through terraces, rivers and climb uphill to climbers capital Namche Bazzar.\\r\\n<strong>03 Day: </strong>Halt day / rest day at Namche- Excursions to panoramic view points, Sherpa museums.\\r\\n<strong>04 Day:</strong> Trekking to Dibuche via the biggest Tengboche Gompa of the region of Everest.\\r\\n<strong>05 Day:</strong> Hiking to Dingboche, walk along the pasture lands and rivers and alpine forest.\\r\\n<strong>06 Day:</strong> Trekking Dingboche to Lobuche via Thulka- walk 4- 5 hours from 4200-4700 meters.\\r\\n<strong>07 Day:</strong> Lobuche to Gorakhshep and hike to Mount Everest base camp - day of dram become true get 5300 meter.\\r\\n<strong>08 Day:</strong> Climb to Kala Patther (Black stone) from Gorakhshep, the highest point of the trip 5560 meter and back to Pangboche.\\r\\n<strong>09 Day:</strong> Hike slowly through the villages, forests Trip back to Namche bazaar.\\r\\n<strong>10 Day:</strong> Easy wrap of Everest base camp trekking, walk to Lukla airport and rest.\\r\\n<strong>11 Day:</strong> Fly Back to Kathmandu, Tribhuvan International Airport."}, "taxonomy": {}, "itinerary": [{"day": 1, "meal": "", "title": "Magnificent flight to Lukla then walk through forest and sherpa settlement to Manju", "richText": "<div id=\\"collapse-1\\" class=\\"panel-collapse collapse show\\" role=\\"tabpanel\\" aria-labelledby=\\"heading-1\\">\\r\\n\\r\\nCollect boxed Breakfast at 6 A.M., drive to Kathmandu Domestic airport. it is about a hour adventure flight with a great view of the Himalayas on the northern side. after landing at Lukla airport, collect your luggage, and meet porters if you need to. you may stop for a Tea break. Now, you are ready to rock and roll for Everest base camp trekking. today’s hiking starts with a downhill walk via Chaurikharka, the last part of the walk is gently uphill. reach Manju for a night's stay in a tea house.\\r\\n\\r\\n</div>", "driveTime": "30 Min fly / Walk 4-4:30 hrs", "elevation": "", "accommodation": ""}, {"day": 2, "meal": "", "title": "Walk through terraces, rivers and climb uphill to climbers capital Namche Bazzar", "richText": "<div id=\\"collapse-2\\" class=\\"panel-collapse collapse show\\" role=\\"tabpanel\\" aria-labelledby=\\"heading-2\\">\\r\\n\\r\\nStart with hot tea and breakfast, and continue to walk in the villages, some farming areas, and river banks. cross a Hillary bridge then climb big uphill to Namche. Namche is the main doorway to the Everest trekking adventure and Expedition trip. today if weather permits have a glimpse of Everest while climbing.\\r\\n\\r\\n</div>", "driveTime": "6 hours", "elevation": "3440m/11283ft", "accommodation": ""}, {"day": 3, "meal": "", "title": "Halt day at Namche- Excursions to panoramic view points, sherpa museums", "richText": "<div id=\\"collapse-3\\" class=\\"panel-collapse collapse show\\" role=\\"tabpanel\\" aria-labelledby=\\"heading-3\\">\\r\\n\\r\\nEnjoy the clear morning view of snow-capped peaks, and local markets. attend the Tibetan market. you may need to do laundry, use a cyber cafe, or buy if you think you will need it because is the last market area to get stuff. visit Museums, and the national park office. hike to Syangboche and Khumjung.\\r\\n\\r\\n</div>", "driveTime": "3 hours", "elevation": "3880 m", "accommodation": ""}, {"day": 4, "meal": "", "title": "Trekking to Dibuche via the biggest Tengboche Gompa of the region of Everest", "richText": "<div id=\\"collapse-4\\" class=\\"panel-collapse collapse show\\" role=\\"tabpanel\\" aria-labelledby=\\"heading-4\\">\\r\\n\\r\\nHave breakfast around 7 am, and start walking before the crowd. enjoy the great view of Mount Everest, Ama Dablam, and more. cross the river and straight climb to Tengboche Monastery, take time to take photos and visit. Have lunch and continue to Debuche for an overnight stay.\\r\\n\\r\\n</div>", "driveTime": "5 hours", "elevation": "3860m/12660ft", "accommodation": ""}, {"day": 5, "meal": "", "title": "Hiking to Dingboche, walk along the pasturelands and rivers and alpine forest", "richText": "<div id=\\"collapse-5\\" class=\\"panel-collapse collapse show\\" role=\\"tabpanel\\" aria-labelledby=\\"heading-5\\">\\r\\n\\r\\nStart in the early morning with your heavy breakfast, and walk through rhododendron forests and alpine vegetation. visit Pangboche Monastery, have tea and coffee then continue to Dingboche.\\r\\n\\r\\n</div>", "driveTime": "5 hours", "elevation": "4410m/14464ft", "accommodation": ""}, {"day": 6, "meal": "", "title": "Trek to Lobuche via Thukla", "richText": "<div id=\\"collapse-6\\" class=\\"panel-collapse collapse show\\" role=\\"tabpanel\\" aria-labelledby=\\"heading-6\\">\\r\\n\\r\\nToday’s walk is not a lung but we are getting high enough already, morning walk starts at 4200 meters. we walk slowly uphill of Thulka and have tea and coffee. today you are above the tree line and can see only alpine grasses and some flowers like blue poppy.\\r\\n\\r\\n</div>", "driveTime": "3 hours", "elevation": "5100m/16728ft", "accommodation": ""}, {"day": 7, "meal": "", "title": "Hike to Gorakshep and have lunch then continue to Mount Everest base camp", "richText": "<div id=\\"collapse-7\\" class=\\"panel-collapse collapse show\\" role=\\"tabpanel\\" aria-labelledby=\\"heading-7\\">\\r\\n\\r\\nYour Dream brought you here, today we trek to Mount Everest base camp and Sleep at Gorakshep where the Everest marathon starts. After breakfast trek to Base camp, carry 1.5 liters of water and some snacks, warm clothes, and be prepared for the cold wind. walk slowly in the crevasse because we walk along the glaciers. stay mainly on the trails.\\r\\n\\r\\n</div>", "driveTime": "7 hours", "elevation": "4910m/16105ft", "accommodation": ""}, {"day": 8, "meal": "", "title": "Climb to Kala Patthar (Black stone) from Gorakhshep, the highest point of the trip 5560 meter and back to Pangboche.", "richText": "<div id=\\"collapse-8\\" class=\\"panel-collapse collapse show\\" role=\\"tabpanel\\" aria-labelledby=\\"heading-8\\">\\r\\n\\r\\nEarly morning three hours sunrise trip to Kalapathhar is a gentle steep hill. the best view of Mount Everest from the entire trekking route, the best view of Mount Pumori, glaciers, Nuptse, and Lhotse, stay here as long as you like then your climbing altitude is over. now we start heading back to Lukla slowly.\\r\\n\\r\\n</div>", "driveTime": "7-8 hours", "elevation": "", "accommodation": ""}, {"day": 9, "meal": "", "title": "Hike slowly through the villages, forests Trip back to Namche bazaar.", "richText": "<div id=\\"collapse-9\\" class=\\"panel-collapse collapse show\\" role=\\"tabpanel\\" aria-labelledby=\\"heading-9\\">\\r\\n\\r\\nWe slowly start hiking and past Dibuche, and Tyangboche. Overnight at Namche the highest biggest settlement.\\r\\n\\r\\n</div>", "driveTime": "6-7 hours", "elevation": "", "accommodation": ""}, {"day": 10, "meal": "", "title": "Easy wrap of Everest base camp trekking, walk to Lukla airport and rest.", "richText": "<div id=\\"collapse-10\\" class=\\"panel-collapse collapse show\\" role=\\"tabpanel\\" aria-labelledby=\\"heading-10\\">\\r\\n\\r\\nTrek back with a slow walk downhill from Namche, cross Hillary Bridge, continue to Jorsalle exit National Park check post, and have lunch at Monjo or Phakding. after lunch continue to Lukla, and enjoy the area, you may do some shopping, and farewell with porters because they do not fly back to Kathmandu.\\r\\n\\r\\n</div>", "driveTime": "7-8 hours", "elevation": "", "accommodation": ""}, {"day": 11, "meal": "", "title": "Fly Back to capital city airport, Tribhuvan International Airport.", "richText": "<div id=\\"collapse-11\\" class=\\"panel-collapse collapse show\\" role=\\"tabpanel\\" aria-labelledby=\\"heading-11\\">\\r\\n\\r\\nAnother exciting flight gives chances to view the long Himalayan range, try to sit on the right-hand side for a better picture. Land in Kathmandu, rest and you may do your pending work, connect home.\\r\\n\\r\\n</div>", "driveTime": "30 min Fly", "elevation": "", "accommodation": ""}], "mainImage": {"url": "https://everestnepaltours.com/wp-content/uploads/2023/12/Everest-Base-Camp-Kalapatthar-Landing-Heli-Tour.jpeg", "title": "Everest-Base-Camp-Kalapatthar-Landing-Heli-Tour", "altText": "Everest-Base-Camp-Kalapatthar-Landing-Heli-Tour", "caption": "Everest-Base-Camp-Kalapatthar-Landing-Heli-Tour", "variants": {}}, "acf_blocks": {"ws_gf_id": "4", "_ws_gf_id": "field_63edec7318284", "ws_block_meals": "Full board during trekking", "_ws_block_meals": "field_63eeee4e072dc", "ws_trip_galleries": ["556", "757"], "_ws_trip_galleries": "field_63ec89128e6ea", "ws_block_start_end": "", "ws_trip_faqs_lists": 4, "_ws_block_start_end": "field_63eeee8b072df", "_ws_trip_faqs_lists": "field_63ede38e351c7", "ws_block_attractions": "Everest Base Camp, Gokyo Lake,  Kalapatthar", "ws_block_best_season": "All season except December & January", "_ws_block_attractions": "field_63eeee1f072da", "_ws_block_best_season": "field_63eeee37072db", "review_number_of_post": "-1", "ws_block_trip_grading": "", "ws_flash_message_text": "", "ws_quick_enquiry_desc": "Fill the form below for your interest.\\r\\n", "ws_trip_include_title": "What's included?", "_review_number_of_post": "field_63ba542aa9a32", "_ws_block_trip_grading": "field_63ec73a6a4716", "_ws_flash_message_text": "field_63ec950194a18", "_ws_quick_enquiry_desc": "field_63edeb1c811ab", "_ws_trip_include_title": "field_63edd6a334286", "starter_kit_section_bg": "bg-white", "ws_block_accommodation": "", "ws_block_max_elevation": "5545 M", "ws_block_video_widgets": "", "ws_flash_message_title": "", "ws_quick_enquiry_title": "Ask to Expert about this trip", "ws_select_content_type": "ws-included", "ws_trip_overview_title": "Overview", "_starter_kit_section_bg": "field_63fc6695edb31", "_ws_block_accommodation": "field_63eeee62072dd", "_ws_block_max_elevation": "field_63eeee07072d9", "_ws_block_video_widgets": "field_63eef38026ee6", "_ws_flash_message_title": "field_63ec94c094a17", "_ws_quick_enquiry_title": "field_63edeb1c7d769", "_ws_select_content_type": "field_63edd755e9729", "_ws_trip_overview_title": "field_63ec808647048", "ws_block_transportation": "Flight from Kathmandu to Lukla to Kathmandu", "ws_trip_galleries_title": "Photo/Visual Gallery", "_ws_block_transportation": "field_63eeee74072de", "_ws_trip_galleries_title": "field_63ec89128acaa", "starter_kit_padding_type": "p-medium", "ws_trip_block_highlights": "<strong>Tenzing Hillary Airport, Namche Bazaar with Sherpa village, Everest Base Camp, Kalapatthar the height view point of Everest Region Trek</strong>", "ws_trip_information_list": 3, "_starter_kit_padding_type": "field_5f8584c998bc2", "_ws_trip_block_highlights": "field_63ec73a6a0d8f", "_ws_trip_information_list": "field_63ec90a574f02", "starter_kit_section_title": "", "_starter_kit_section_title": "field_63ec948c94a16", "starter_kit_enable_section": "1", "ws_trip_faqs_section_title": "Trip FAQs", "_starter_kit_enable_section": "field_63ec90a5664e4", "_ws_trip_faqs_section_title": "field_63ede33e5b304", "starter_kit_section_padding": "", "ws_trip_include_description": "<ul>\\r\\n \\t<li>All accommodations during trekking</li>\\r\\n \\t<li>Cost of National park entry</li>\\r\\n \\t<li>Trekking guide from Kathmandu</li>\\r\\n \\t<li>1 porter for 2 travelers</li>\\r\\n \\t<li>Flight tickets to Lukla and back to Kathmandu</li>\\r\\n \\t<li>Flight ticket of trekking guide</li>\\r\\n \\t<li>Airport transfer (Pickup &amp; Drop) from hotel</li>\\r\\n \\t<li>Supervision of all arrangements</li>\\r\\n</ul>", "_starter_kit_section_padding": "field_5f3e0f86a2634", "_ws_trip_include_description": "field_63edd6a337cd0", "ws_trip_overview_description": "<strong>Everest base camp Trekking cost and plan in depth – reasonable budget price\\r\\n</strong>\\r\\n\\r\\nDream trip of a lifetime on land, Everest base camp trekking is the most famous trekking adventure in the world. Everest is the highest peak,  8848.86 meters (29,029 feet) but base camp is 5300 meters (17,600 feet) only.  Join our well-organized small group trekking to Everest base camp in two weeks or a private custom itinerary also available on a daily departure basis.\\r\\n\\r\\nSpend a few days in the historic cultural capital Kathmandu where Buddhist stupas, Hindu temples, and five-hundred-year-old royal palaces are making the city vibrant.  Spin the prayer wheels, and chant the mantra ‘OM MANI PADME HUM’ meaning HAIL TO THE JEWEL ON THE LOTUS.\\r\\n\\r\\nStroll around the 17th-century alleyways. Start hiking the trails with the sound of yak bells, and trekking porters’ melodious songs.  Meditate in the prayer hall while monks are praying and drink Tibetan tea with monks, chanting their mantras together. Enjoy Sherpa soup (Sherpa stew), Yak steak, Tongba (alcohol for Sherpa), Raksi (rice wine) drink Salt tea or butter tea to keep you warm during the morning. Talk to Sherpa Porter and try to carry their heavy loads. Learn to cook Dal-Bhat and taste with our trekking safe.\\r\\n\\r\\nFly to Lukla and follow the traditional trekking route but our guide organizes through visits to hidden gems and surprises every day. make photographs of sunrise and sunset views on the summit of Everest, Amadablam, and more…  enjoy the holiday. plan in advance and also for <a href=\\"https://www.nepalimmigration.gov.np/\\" target=\\"_blank\\" rel=\\"noopener\\">the visa process</a> to enter Nepal.\\r\\n<h3>Outline Itinerary</h3>\\r\\n<strong>01 Day:</strong> Early morning, Magnificent flight to Lukla then walk through forest and Sherpa settlement to Manju.\\r\\n<strong>02 Day:</strong> Walk through terraces, rivers and climb uphill to climbers capital Namche Bazzar.\\r\\n<strong>03 Day: </strong>Halt day / rest day at Namche- Excursions to panoramic view points, Sherpa museums.\\r\\n<strong>04 Day:</strong> Trekking to Dibuche via the biggest Tengboche Gompa of the region of Everest.\\r\\n<strong>05 Day:</strong> Hiking to Dingboche, walk along the pasture lands and rivers and alpine forest.\\r\\n<strong>06 Day:</strong> Trekking Dingboche to Lobuche via Thulka- walk 4- 5 hours from 4200-4700 meters.\\r\\n<strong>07 Day:</strong> Lobuche to Gorakhshep and hike to Mount Everest base camp - day of dram become true get 5300 meter.\\r\\n<strong>08 Day:</strong> Climb to Kala Patther (Black stone) from Gorakhshep, the highest point of the trip 5560 meter and back to Pangboche.\\r\\n<strong>09 Day:</strong> Hike slowly through the villages, forests Trip back to Namche bazaar.\\r\\n<strong>10 Day:</strong> Easy wrap of Everest base camp trekking, walk to Lukla airport and rest.\\r\\n<strong>11 Day:</strong> Fly Back to Kathmandu, Tribhuvan International Airport.", "_ws_trip_overview_description": "field_63ec83089dd8e", "starter_kit_testimonial_title": "Traveler's Reviews", "_starter_kit_testimonial_title": "field_63ba53af6b053", "ws_trip_fact_short_description": "Everest base camp trekking cost and plan in depth with cheapest budget price ", "ws_trip_faqs_lists_0_faq_title": "Where is Everest Base Camp? how high is it ?", "ws_trip_faqs_lists_1_faq_title": "How long does it take to climb Mount Everest Base Camp?", "ws_trip_faqs_lists_2_faq_title": "How much does it cost to trek Everest base camp ?", "ws_trip_faqs_lists_3_faq_title": "Clothing for Everest base camp trekking ?", "_ws_trip_fact_short_description": "field_63ec73a69d305", "_ws_trip_faqs_lists_0_faq_title": "field_63ede3af351c8", "_ws_trip_faqs_lists_1_faq_title": "field_63ede3af351c8", "_ws_trip_faqs_lists_2_faq_title": "field_63ede3af351c8", "_ws_trip_faqs_lists_3_faq_title": "field_63ede3af351c8", "ws_trip_information_list_0_di_days": "01", "ws_trip_information_list_1_di_days": "02", "ws_trip_information_list_2_di_days": "03", "ws_trip_information_list_3_di_days": "04", "ws_trip_information_list_4_di_days": "05", "ws_trip_information_list_5_di_days": "06", "ws_trip_information_list_6_di_days": "07", "ws_trip_information_list_7_di_days": "08", "ws_trip_information_list_8_di_days": "09", "ws_trip_information_list_9_di_days": "10", "_ws_trip_information_list_0_di_days": "field_63ec958b8c799", "_ws_trip_information_list_1_di_days": "field_63ec958b8c799", "_ws_trip_information_list_2_di_days": "field_63ec958b8c799", "_ws_trip_information_list_3_di_days": "field_63ec958b8c799", "_ws_trip_information_list_4_di_days": "field_63ec958b8c799", "_ws_trip_information_list_5_di_days": "field_63ec958b8c799", "_ws_trip_information_list_6_di_days": "field_63ec958b8c799", "_ws_trip_information_list_7_di_days": "field_63ec958b8c799", "_ws_trip_information_list_8_di_days": "field_63ec958b8c799", "_ws_trip_information_list_9_di_days": "field_63ec958b8c799", "ws_trip_information_list_10_di_days": "11", "_ws_trip_information_list_10_di_days": "field_63ec958b8c799", "ws_trip_faqs_lists_0_faqs_description": "Located in Nepal, Base camp is located at 5300 meter, Everest is 8,848 meter from sea level.", "ws_trip_faqs_lists_1_faqs_description": "Two weeks for trekking in both ways but allow few extra days for preparations.", "ws_trip_faqs_lists_2_faqs_description": "Depend on hotels choices and services need. Minimum cost is USD 1000 per person", "ws_trip_faqs_lists_3_faqs_description": "Be prepared for freezing zero, so bring Down Jackets and all warm clothes including sleeping bag.", "_ws_trip_faqs_lists_0_faqs_description": "field_63ede3bf351c9", "_ws_trip_faqs_lists_1_faqs_description": "field_63ede3bf351c9", "_ws_trip_faqs_lists_2_faqs_description": "field_63ede3bf351c9", "_ws_trip_faqs_lists_3_faqs_description": "field_63ede3bf351c9", "ws_trip_information_list_0_ws_itinerary_food": "", "ws_trip_information_list_1_ws_itinerary_food": "", "ws_trip_information_list_2_ws_itinerary_food": "", "ws_trip_inf