od": "Breakfast", "ws_trip_information_list_12_ws_itinerary_food": "Breakfast, Lunch & Dinner", "ws_trip_information_list_13_ws_itinerary_food": "Breakfast", "ws_trip_information_list_14_ws_itinerary_food": "Breakfast", "ws_trip_information_list_1_ws_itinerary_hotel": "3star to Luxury hotels", "ws_trip_information_list_1_ws_itinerary_title": "Sightseeing in Lhasa (Potala Palace, Jokhang Temple, and Barkhor Bazaar)", "ws_trip_information_list_2_ws_itinerary_hotel": "3star to Luxury hotels", "ws_trip_information_list_2_ws_itinerary_title": "Sightseeing of Drepung, Sera Monasteries & Norbulingka Palace", "ws_trip_information_list_3_ws_itinerary_hotel": "3star to Luxury hotels", "ws_trip_information_list_3_ws_itinerary_title": "Drive to Shigatse via Lake Yamdrok Lake and Gyantse Visit Kumbum Monastery, Pelkor Chöde Monastery, and drive to Shigatse", "ws_trip_information_list_4_ws_itinerary_hotel": "3star to Luxury hotels", "ws_trip_information_list_4_ws_itinerary_title": "Visit Tashilhunpo Monastery, and drive to Shegar", "ws_trip_information_list_5_ws_itinerary_hotel": "3star to Luxury hotels", "ws_trip_information_list_5_ws_itinerary_title": "Early morning drive to Rongbuk (Everest base camp), and drive back to Shigatse.", "ws_trip_information_list_6_ws_itinerary_hotel": "3star to Luxury hotels", "ws_trip_information_list_6_ws_itinerary_title": "Drive to Namtso Lake (Damxung Town)", "ws_trip_information_list_7_ws_itinerary_hotel": "3star to Luxury hotels", "ws_trip_information_list_7_ws_itinerary_title": "Drive Namtso Lake to Lhasa", "ws_trip_information_list_8_ws_itinerary_hotel": "3star to Luxury hotels", "ws_trip_information_list_8_ws_itinerary_title": "Drive to the airport and fly to Kathmandu, Short tour of Kathmandu (Pashupati & Boudha Stupa)", "ws_trip_information_list_9_ws_itinerary_hotel": "3star to Luxury hotels", "ws_trip_information_list_9_ws_itinerary_title": "Kathmandu sightseeing (Swoyambhunath, Bhaktapur Durbar Square, and Changunarayan", "_ws_trip_inf