ys\\":\\"field_63ec958b8c799\\",\\"ws_trip_information_list_6_ws_itinerary_title\\":\\"Punakha Sightseeing\\",\\"_ws_trip_information_list_6_ws_itinerary_title\\":\\"field_63ec945663e31\\",\\"ws_trip_information_list_6_ws_itinerary_Elevation\\":\\"\\",\\"_ws_trip_information_list_6_ws_itinerary_Elevation\\":\\"field_63ec967a59e99\\",\\"ws_trip_information_list_6_ws_itinerary_duration\\":\\"\\",\\"_ws_trip_information_list_6_ws_itinerary_duration\\":\\"field_63ec96a0878df\\",\\"ws_trip_information_list_6_ws_itinerary_hotel\\":\\"\\",\\"_ws_trip_information_list_6_ws_itinerary_hotel\\":\\"field_63ec96e3878e0\\",\\"ws_trip_information_list_6_ws_itinerary_food\\":\\"\\",\\"_ws_trip_information_list_6_ws_itinerary_food\\":\\"field_63ec96f1878e1\\",\\"ws_trip_information_list_6_ws_itinerary_description\\":\\"Drive from Thimphu to Punakha via Dochu La Pass\\\\r\\\\n- Dochula Pass\\\\r\\\\n- Punakha Dzong\\\\r\\\\n- Suspension Bridge\\\\r\\\\n- Chimi Lhakhang, Temple of fertility\\\\r\\\\n\\\\u003cstrong\\\\u003eDistance:\\\\u003c/strong\\\\u003e 2.5 hours drive\\",\\"_ws_trip_information_list_6_ws_itinerary_description\\":\\"field_63ec9456679f6\\",\\"ws_trip_information_list_7_di_days\\":\\"08\\",\\"_ws_trip_information_list_7_di_days\\":\\"field_63ec958b8c799\\",\\"ws_trip_information_list_7_ws_itinerary_title\\":\\"Punakha to Paro \\",\\"_ws_trip_information_list_7_ws_itinerary_title\\":\\"field_63ec945663e31\\",\\"ws_trip_information_list_7_ws_itinerary_Elevation\\":\\"\\",\\"_ws_trip_information_list_7_ws_itinerary_Elevation\\":\\"field_63ec967a59e99\\",\\"ws_trip_information_list_7_ws_itinerary_duration\\":\\"\\",\\"_ws_trip_information_list_7_ws_itinerary_duration\\":\\"field_63ec96a0878df\\",\\"ws_trip_information_list_7_ws_itinerary_hotel\\":\\"\\",\\"_ws_trip_information_list_7_ws_itinerary_hotel\\":\\"field_63ec96e3878e0\\",\\"ws_trip_information_list_7_ws_itinerary_food\\":\\"\\",\\"_ws_trip_information_list_7_ws_itinerary_food\\":\\"field_63ec96f1878e1\\",\\"ws